cat > /workspace/tmp/t/test_refs.py <<'PYEOF'
import json, sys, struct
sys.path.insert(0,'/workspace/tmp/t')
from harness import *
D=4294967295; RE={'error':'rejected'}
AB=svc(('A',1),('B',2))
imgAB={'accept':[False,False,True],'rows':[[1,D],[D,2],[D,D]]}
imgA={'accept':[False,True],'rows':[[1,D],[D,D]]}
def runjob(events, services=AB, limits=None):
    return jrun({'jobs':[job(services, events, limits)]})['results'][0]['events']
st=lambda e,p:{'op':'stage','epoch':e,'policy':p}
co=lambda e:{'op':'commit','epoch':e}
re_=lambda e:{'op':'retire','epoch':e}
sp=lambda u,s:{'op':'spawn','unit':u,'service':s}
bg=lambda u,r:{'op':'begin','unit':u,'rid':r}
fi=lambda u,r:{'op':'finish','unit':u,'rid':r}
ex=lambda u:{'op':'exit','unit':u}
cl=lambda p,c:{'op':'clone','parent':p,'child':c}
op=lambda c:{'op':'open','connection':c}
sn=lambda u,r,c,s,d:{'op':'send','unit':u,'rid':r,'connection':c,'stream':s,'destination':d}
rv=lambda c,s,u,r:{'op':'recv','connection':c,'stream':s,'unit':u,'rid':r,'wire':None}
cz=lambda c:{'op':'close','connection':c}
sto=lambda u,r,f:{'op':'store','unit':u,'rid':r,'file':f}
ld=lambda f,u,r:{'op':'load','file':f,'unit':u,'rid':r}
ul=lambda f:{'op':'unlink','file':f}
ins={'op':'inspect'}
A1=[0,1,1]; B1=[0,2,1]

def refs(seq):
    out = runjob(seq)
    last = [e for e in out if 'images' in e][-1]
    return last['images']

# reference accounting across every holding object
check('refs contexts+packet+file', refs([st(1,'match(A,B) allow;'), st(2,'match(A) allow;'), co(1), sp(A1,'A'), sp(B1,'B'),
      bg(A1,1), bg(A1,2), op([1,1]), sn(A1,1,[1,1],1,'B'), rv([1,1],1,B1,1), sto(A1,2,[1,1]), ins]),
      [[1,3,2,4],[2,2,1,0]])
check('refs after finish source', refs([st(1,'match(A,B) allow;'), st(2,'match(A) allow;'), co(1), sp(A1,'A'), sp(B1,'B'),
      bg(A1,1), bg(A1,2), op([1,1]), sn(A1,1,[1,1],1,'B'), rv([1,1],1,B1,1), sto(A1,2,[1,1]), fi(A1,2), ins]),
      [[1,3,2,3],[2,2,1,0]])
check('refs after unlink', refs([st(1,'match(A,B) allow;'), co(1), sp(A1,'A'), sp(B1,'B'), bg(A1,1), sto(A1,1,[1,1]), ul([1,1]), ins]),
      [[1,3,2,1]])
check('refs overwrite same epoch', refs([st(1,'match(A,B) allow;'), co(1), sp(A1,'A'), bg(A1,1), bg(A1,2), sto(A1,1,[1,1]),
      sto(A1,2,[1,1]), ins]), [[1,3,2,3]])
check('refs overwrite other epoch', refs([st(1,'match(A,B) allow;'), st(2,'match(A) allow;'), co(1), sp(A1,'A'), bg(A1,1),
      sto(A1,1,[1,1]), co(2), bg(A1,2), sto(A1,2,[1,1]), ins]),
      [[1,3,2,1],[2,2,1,2]])
check('refs clone and exit parent', refs([st(1,'match(A,B) allow;'), co(1), sp(A1,'A'), bg(A1,1), cl(A1,B1), ex(A1), ins]),
      [[1,3,2,1]])
check('refs packet close', refs([st(1,'match(A,B) allow;'), co(1), sp(A1,'A'), sp(B1,'B'), bg(A1,1), op([1,1]),
      sn(A1,1,[1,1],1,'B'), rv([1,1],1,B1,1), cz([1,1]), ins]), [[1,3,2,2]])
check('retire blocked then allowed', runjob([st(1,'match(A,B) allow;'), st(2,'match(A) allow;'), co(2), sp(A1,'A'), bg(A1,1),
      sto(A1,1,[1,1]), re_(2), fi(A1,1), ul([1,1]), re_(2), ins]),
      [{'ok':True,'epoch':1,'image':imgAB},{'ok':True,'epoch':2,'image':imgA},{'ok':True},{'ok':True},
       {'ok':True,'epoch':2,'state':1},{'ok':True},RE,{'ok':True,'allow':True},{'ok':True},{'ok':True},
       {'ok':True,'active':2,'images':[],'units':1,'contexts':0,'connections':0,'packets':0,'files':0}])
sys.exit(summary())
PYEOF
cd /workspace/tmp/t && python3 test_refs.py 2>&1 | grep -E "^FAIL|failures"
